editorial('/personal-story/','Family & personal story','BEYOND THE MUSIC','THE PEOPLE.<br><span>THE PERSPECTIVE.</span>','A personal chapter in the story of Kaeleb Savon Heck.',[('THE PERSON BEHIND THE ARTIST',['Music is one part of Kaeleb’s public creative identity. His channels also share life in the Philippines and his perspective as a blind creator, giving listeners a way to connect with the person behind the releases.','Virginia roots and a home in the Philippines are part of the story he shares through the Mr. Blindbandit name.']),('FAMILY CONNECTIONS',['For this website, Kaeleb has named his daughter Madeline Heck, mother Celyne Heck, sister Kelsey Heck, and brother Christopher Andrew Hall Jr. Family appears here as part of his own story.','Follow the official channels for the personal moments he chooses to make public.']),('KEEP EXPLORING',['Read the <a href="/biography/">biography</a> for a concise overview, visit the <a href="/timeline/">timeline</a> for catalog milestones, or follow the <a href="/connect/">official social channels</a>.'])])

access=section('<div class="preference-panel"><h2>MAKE IT COMFORTABLE.</h2><p>These choices apply on this device. Motion is on by default.</p><div class="actions"><button data-preference="large" aria-pressed="false">Larger text</button><button data-preference="contrast" aria-pressed="false">High contrast</button><button data-preference="paused" aria-pressed="false">Pause motion</button></div></div>'+tiles([('NAVIGATION','Keyboard &amp; screen readers','Find headings, skip navigation, and move through the site.','/accessibility/navigation/'),('PLAYBACK','Listening controls','Use the persistent Spotify player and external listening links.','/accessibility/listening/'),('FEEDBACK','Report a barrier','Tell us the page and what prevented you from using it.','/connect/')])+prose('ACCESSIBILITY IN PRACTICE',['The site uses descriptive headings, form labels, image descriptions, keyboard focus indicators, and a skip-to-content link. Community messages are written as text and can be read without interacting with a player.','Spotify, YouTube, Apple Music, and Jotform supply their own embedded interfaces. Direct links are provided so you can open those services separately if their embedded controls are difficult to use.'])+prose('HELP IMPROVE THE EXPERIENCE',['Email business@mrblindbandit.net with the page address, your device or assistive technology, and a description of the barrier. No claim of full conformance is made without a complete accessibility audit.']))
publish('/accessibility/','Accessibility hub','ACCESS / PREFERENCES','YOUR WAY<br><span>THROUGH.</span>','Navigation and listening choices for the official Mr. Blindbandit website.',access)
editorial('/accessibility/navigation/','Keyboard & screen-reader navigation','ACCESSIBILITY / NAVIGATION','FIND YOUR<br><span>WAY AROUND.</span>','Practical navigation guidance for the site.',[('START WITH CONTENT',['The first keyboard link is “Skip to content.” Use it to reach the main page. Each page has one primary heading; section headings organize the rest of the content.','On mobile, the Menu button expands the main navigation and announces whether it is open. The Explore page lists all public sections and includes a page search.']),('KEYBOARD CONTROLS',['Use Tab and Shift+Tab to move between links and controls. Activate buttons with Enter or Space. Native form controls use their usual keyboard behavior. Dialogs have a labeled Close button.','The site does not install single-letter shortcuts that could conflict with screen readers. After an internal page change, focus moves to the new page’s main heading.']),('COMMUNITY &amp; FORMS',['Community fields have visible labels. Save failures keep your text in the form. Public posts and comments use plain text rather than requiring images or video.','Sign-in opens as a full navigation to the platform’s ChatGPT sign-in flow. The site never asks for your ChatGPT password in a community form.'])])
editorial('/accessibility/listening/','Accessible listening','ACCESSIBILITY / AUDIO','LISTEN ON<br><span>YOUR TERMS.</span>','Choose when players load, how you listen, and where playback happens.',[('NO AUDIO ON ARRIVAL',['Visiting a page does not start music. Choose a Spotify player button to load the player, then use Spotify’s controls to begin playback.','The listening dock stays on screen as you follow ordinary internal links. Minimize it to give more room to the page, expand it to reach the controls, or close it to stop that player.']),('OPEN THE PLATFORM DIRECTLY',['Every release retains an external listening option. Open Spotify or Apple Music directly if that works better with your device or assistive technology. Availability, previews, and account requirements are controlled by the listening platform.','YouTube video players load when requested. Captions and transcripts depend on what is available for the original video; this site does not invent transcripts for videos it has not transcribed.']),('WHEN PLAYBACK MAY RESTART',['A browser refresh, a full sign-in navigation, opening a new tab, or leaving this website starts a new page session. Those actions can stop the embedded player. Normal in-site navigation preserves it.'])])

