publish('/contact/forms/','Professional inquiries','FEATURES / PRODUCTION / PRESS','LET’S MAKE<br><span>A CONNECTION.</span>','Prepare a focused inquiry for the artist’s business email.',section('''<div class="submission-layout"><form id="inquiry-form" class="brief-form"><label>Inquiry type<select name="kind"><option>Feature collaboration</option><option>Production</option><option>Interview</option><option>Performance or appearance</option><option>Music licensing</option><option>Sponsorship or brand partnership</option></select></label><label>Your name or organization<input name="name" maxlength="120" required></label><label>Reply email<input type="email" name="email" required></label><label>Project details<textarea name="message" rows="7" maxlength="3000" required></textarea></label><label>Relevant link (optional)<input name="reference" type="url"></label><button class="button" type="submit">Prepare email inquiry</button><p id="inquiry-status" role="status"></p><a id="send-inquiry" class="button" hidden>Open email app to send</a><p class="small">This form prepares an email on your device. It has not been delivered until you send it in your email app.</p></form><aside class="side-note"><h3>Include the useful details</h3><p>Share the track or project, intended use, timing, and any budget range. For interviews, include your outlet. For performances, include the venue and date. For licensing, identify the recording and where it will appear.</p><a href="/submit/">Submitting a demo? Use the music form.</a><a href="/project-brief/">Build a more detailed project brief</a></aside></div>'''))

