# Make Spotify the primary player while preserving exact Apple release links.
def transform_records(s):
    def record(m):
        block=m.group(0);art=re.search(r'/assets/releases/(\d+)\.jpg',block)
        if not art:return block
        id=art.group(1);r=next((r for r in catalog if r['id']==id),None)
        if not r:return block
        title=esc(re.sub(r' - (Single|EP)$','',r['title']))
        u=spotify.get(id);search='https://open.spotify.com/search/'+quote(r['artist']+' '+r['title'])
        # Remove secondary embedded Apple controls; its direct link stays available.
        block=re.sub(r'<button class="preview-link".*?</button>','',block)
        primary=('<button class="preview-link" data-spotify="'+u+'" data-name="'+title+'">Play on Spotify</button>' if u else '<a class="record-link" href="'+search+'">Find on Spotify ↗</a>')
        return block.replace('<a class="record-link"',primary+'<a class="record-link"',1)
    return re.sub(r'<article class="record".*?</article>',record,s,flags=re.S)

